    """Evaluates a mathematical expression using the Shunting Yard algorithm and Reverse Polish Notation (RPN) for computation."""

    def precedence(op: str) -> int:
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_operator(operators: list, values: list):
        right = values.pop()
        left = values.pop()
        operator = operators.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(left / right)

    def to_rpn(tokens: list) -> list:
        output = []
        operators = []

        for token in tokens:
            if token.isnumeric() or '.' in token:
                output.append(float(token))
            elif token in ('+', '-', '*', '/'):
                while (operators and precedence(operators[-1]) >= precedence(token)):
                    apply_operator(operators, output)
                operators.append(token)
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators and operators[-1] != '(':
                    apply_operator(operators, output)
                operators.pop()  # discard the '('

        while operators:
            apply_operator(operators, output)

        return output

    def tokenize(expression: str) -> list:
        tokens = []
        num_buffer = []
        for char in expression:
            if char.isdigit() or char == '.':
                num_buffer.append(char)
            else:
                if num_buffer:
                    tokens.append(''.join(num_buffer))
                    num_buffer = []
                if char in "+-*/()":
                    tokens.append(char)
                elif char.isspace():
                    continue
        if num_buffer:
            tokens.append(''.join(num_buffer))
        return tokens

    tokens = tokenize(expr)
    values_rpn = to_rpn(tokens)
    return values_rpn[0]

