def evaluate(expr: str) -> float:
    """Evaluates a mathematical expression using the shunting yard algorithm to convert to Reverse Polish Notation (RPN) for evaluation."""

    def shunting_yard(expression):
        output_queue = []
        operator_stack = []
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        for token in tokenize(expression):
            if token.isdigit() or '.' in token:  # Number
                output_queue.append(float(token))
            elif token in precedence:  # Operator
                while (operator_stack and operator_stack[-1] != '(' and
                       precedence[token] <= precedence[operator_stack[-1]]):
                    output_queue.append(operator_stack.pop())
                operator_stack.append(token)
            elif token == '(':
                operator_stack.append(token)
            elif token == ')':
                while operator_stack and operator_stack[-1] != '(':
                    output_queue.append(operator_stack.pop())
                operator_stack.pop()  # discard the left parenthesis
        while operator_stack:
            output_queue.append(operator_stack.pop())
        return output_queue

    def tokenize(expression):
        tokens = []
        current_number = ''
        for char in expression:
            if char.isdigit() or char == '.':
                current_number += char
            else:
                if current_number:
                    tokens.append(current_number)
                    current_number = ''
                if char in "+-*/()":
                    tokens.append(char)
                elif char.isspace():
                    continue
        if current_number:
            tokens.append(current_number)
        return tokens

    def evaluate_rpn(rpn_expression):
        stack = []
        for token in rpn_expression:
            if isinstance(token, float):
                stack.append(token)
            else:  # Operator
                b, a = stack.pop(), stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(a / b)
        return stack[0]

    rpn = shunting_yard(expr)
    return evaluate_rpn(rpn)

